syntax:
// A is r1 x c1, B is r2 x c2, and c1 must equal r2
// C is r1 x c2
for (int i = 0; i < r1; i++) {          // each row of A
    for (int j = 0; j < c2; j++) {      // each column of B
        int sum = 0;                    // reset for EVERY cell
        for (int k = 0; k < c1; k++) {  // c1 (same as r2) pairs to multiply
            sum += A[i][k] * B[k][j];   // row i of A with column j of B
        }
        C[i][j] = sum;                  // store the finished cell
    }
}

sample.code:
#include <iostream>
using namespace std;

int main() {
    int A[2][2] = {{1, 2}, {3, 4}};
    int B[2][2] = {{5, 6}, {7, 8}};
    int C[2][2];
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            C[i][j] = 0;
            for (int k = 0; k < 2; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            cout << C[i][j] << " ";
        }
        cout << endl;
    }
    return 0;
}

