#include <iostream>
using namespace std;

int main() {
    int A[3][3], B[3][3], C[3][3];
    int r1, c1, r2, c2;
    cin >> r1 >> c1;
    for (int i = 0; i < r1; i++)
        for (int j = 0; j < c1; j++)
            cin >> A[i][j];
    cin >> r2 >> c2;
    for (int i = 0; i < r2; i++)
        for (int j = 0; j < c2; j++)
            cin >> B[i][j];
    if (c1 != r2) {
        cout << "Multiplication not possible" << endl;
        return 0;
    }
    for (int i = 0; i < r1; i++) {
        for (int j = 0; j < c2; j++) {
            int sum = 0;
            for (int k = 0; k < c1; k++) {
                sum += A[i][k] * B[k][j];
            }
            C[i][j] = sum;
        }
    }
    for (int i = 0; i < r1; i++) {
        for (int j = 0; j < c2; j++) {
            cout << C[i][j] << " ";
        }
        cout << endl;
    }
    return 0;
}

